import hashlib
import json
from dataclasses import dataclass
from datetime import datetime, timezone

# --- HTTP Idempotency-Key (Postgres) ---
# table idempotency_keys(
#   key text not null,
#   scope text not null,  -- user or route
#   request_hash text not null,
#   status text not null, -- processing|completed|failed
#   response_code int,
#   response_body jsonb,
#   created_at timestamptz not null,
#   primary key (scope, key)
# )

def request_hash(body: bytes) -> str:
    return hashlib.sha256(body).hexdigest()

async def with_idempotency(session, scope: str, key: str, body: bytes, handler):
    rh = request_hash(body)
    existing = await session.get(IdempotencyRow, (scope, key))
    if existing:
        if existing.request_hash != rh:
            raise ConflictError('idempotency_key_reuse_mismatch')
        if existing.status == 'completed':
            return existing.response_code, existing.response_body
        # processing: either wait, 409, or re-enter if crash-safe design
    row = IdempotencyRow(scope=scope, key=key, request_hash=rh, status='processing')
    session.add(row)
    try:
        await session.flush()
    except IntegrityError:
        await session.rollback()
        return await with_idempotency(session, scope, key, body, handler)
    code, resp = await handler()
    row.status = 'completed'
    row.response_code = code
    row.response_body = resp
    await session.commit()
    return code, resp

# --- Worker retry classification ---
@dataclass
class RetryDecision:
    retry: bool
    delay_s: float

def classify(exc: BaseException, attempt: int, max_attempts: int = 5) -> RetryDecision:
    if attempt >= max_attempts:
        return RetryDecision(False, 0)
    if isinstance(exc, (TimeoutError, ConnectionError)):
        delay = min(60, (2 ** attempt)) + jitter()
        return RetryDecision(True, delay)
    if isinstance(exc, PermanentError):
        return RetryDecision(False, 0)
    # default: unknown → limited retry then DLQ
    return RetryDecision(attempt < 3, min(30, 2 ** attempt))

